    d_ts timestamp(3) without time zone,
    CONSTRAINT chrt_lst_t_flags_check CHECK (((archived_in = ANY (ARRAY[0, 1])) AND (a_in = ANY (ARRAY[0, 1]))))
);

CREATE TABLE public.chrt_mbr_rel_t (
    chrt_mbr_id text NOT NULL,
    college_id text NOT NULL,
    chrt_id text NOT NULL,
    user_id text NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    CONSTRAINT chrt_mbr_rel_t_a_in_check CHECK ((a_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public.chrt_lst_t
    ADD CONSTRAINT chrt_lst_t_pkey PRIMARY KEY (chrt_id);

ALTER TABLE ONLY public.chrt_mbr_rel_t
    ADD CONSTRAINT chrt_mbr_rel_t_pkey PRIMARY KEY (chrt_mbr_id);

CREATE UNIQUE INDEX chrt_lst_t_college_id_chrt_nm_key ON public.chrt_lst_t USING btree (college_id, chrt_nm);

CREATE UNIQUE INDEX chrt_mbr_rel_t_chrt_id_user_id_key ON public.chrt_mbr_rel_t USING btree (chrt_id, user_id);

CREATE INDEX chrt_mbr_rel_t_user_id_idx ON public.chrt_mbr_rel_t USING btree (user_id);

CREATE TRIGGER chrt_lst_t_audit_timestamps BEFORE UPDATE ON public.chrt_lst_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

CREATE TRIGGER chrt_mbr_rel_t_audit_timestamps BEFORE UPDATE ON public.chrt_mbr_rel_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public.chrt_lst_t
    ADD CONSTRAINT chrt_lst_t_btch_id_fkey FOREIGN KEY (btch_id) REFERENCES public.btch_lst_t(btch_id) ON UPDATE CASCADE ON DELETE SET NULL;

ALTER TABLE ONLY public.chrt_mbr_rel_t
